  var PATTERNS = [];

  var SEV = '(Low|Medium|High|Critical|Unrated)';
  function P(src, fn) { PATTERNS.push([new RegExp('^' + src + '$'), fn]); }
  function num(s) { return String(s).replace('.', ','); }
