  P('Same gap on every alert \\(±(\\d+) s\\): most likely the VM clock, not slow detection\\.', function (m) { return 'Même écart sur chaque alerte (±' + m[1] + ' s) : très probablement l’horloge de la VM, pas une détection lente.'; });
  P('Every alert arrived (.+) after its event, within (\\d+) s of each other\\. A constant gap means the Windows VM clock is behind the Wazuh server; sync it before using detection time as a KPI\\.', function (m) {
    return 'Chaque alerte est arrivée ' + m[1] + ' après son événement, à ' + m[2] + ' s près. Un écart constant signifie que l’horloge de la VM Windows retarde sur le serveur Wazuh ; synchronisez-la avant d’utiliser le délai de détection comme KPI.'; });
  P('Detection took (.+) on average\\. Plan triage around that delay\\.', function (m) { return 'La détection a pris ' + m[1] + ' en moyenne. Organisez le tri en tenant compte de ce délai.'; });
  P('The AI made (\\d+) claims? that the log contradicted\\. Keep the human check; never act on unverified AI output\\.', function (m) {
    return 'L’IA a fait ' + m[1] + ' affirmation(s) contredite(s) par le journal. Gardez la vérification humaine ; n’agissez jamais sur une sortie d’IA non vérifiée.'; });
  P('(INC-\\d+) \\((.+)\\): Wazuh alone rated it ' + SEV + '; in context it is ' + SEV + '\\. Correlate related alerts instead of reading them one by one\\.', function (m, L) {
    return m[1] + ' (' + L(m[2].charAt(0).toUpperCase() + m[2].slice(1)).toLowerCase() + ') : Wazuh seul l’a classé ' + L(m[3]) + ' ; dans son contexte il est ' + L(m[4]) + '. Corrélez les alertes liées au lieu de les lire une par une.'; });
  P('(INC-\\d+) · ' + SEV + ' · within ([^:]+): ([\\s\\S]+?)( \\(AI suggestion, not yet selected\\))?', function (m, L) {
    return m[1] + ' · ' + L(m[2]) + ' · sous ' + L(m[3]) + ' : ' + L(m[4]) + (m[5] ? ' (suggestion de l’IA, pas encore retenue)' : ''); });
  // headings and labels with ids
  P('Claims checked against the log · (\\d+) match, (\\d+) wrong', function (m) { return 'Affirmations vérifiées dans le journal · ' + m[1] + ' conformes, ' + m[2] + ' fausses'; });
  P('Claims to verify \\((\\d+)\\)', function (m) { return 'Affirmations à vérifier (' + m[1] + ')'; });
  P('Claims verified (\\d+) of (\\d+)', function (m) { return 'Affirmations vérifiées : ' + m[1] + ' sur ' + m[2]; });
  P('Decided (.+)', function (m) { return 'Décidé le ' + m[1]; });
