  P('Rule (\\d+)', function (m) { return 'Règle ' + m[1]; });
  P('Scenario (\\d+)( · INC-\\d+)?', function (m) { return 'Scénario ' + m[1] + (m[2] || ''); });
  P('Team 3 summary received( .+)?', function (m) { return 'Synthèse de l’équipe 3 reçue' + (m[1] ? ' à' + m[1] : ''); });
  P('Wazuh alert (\\S+) \\(\\+(.+)\\)', function (m) { return 'Alerte Wazuh ' + m[1] + ' (+' + m[2] + ')'; });
